// Get research prompts from global cache
const promptSelector = require('/home/node/.n8n/custom/functions/promptSelector.js');
const prompts = global.prompts || {};

// Extract research parameters
const researchType = items[0].json.research_type || 'Trending_Topics';
const platform = items[0].json.platform || 'all';
const variables = {
  INDUSTRY: items[0].json.industry || 'technology',
  NICHE: items[0].json.niche || 'AI',
  TOPIC: items[0].json.topic || 'artificial intelligence',
  GEO: process.env.TRENDS_GEO || 'US',
  COMPETITOR: items[0].json.competitor || '',
  QUERY: items[0].json.query || items[0].json.topic,
  MACROCOSMOS_KEY: process.env.MACROCOSMOS_KEY,
  RITETAG_KEY: process.env.RITETAG_KEY,
  BUZZSUMO_KEY: process.env.BUZZSUMO_KEY,
  SERPAPI_KEY: process.env.SERPAPI_KEY,
  PPLX_KEY: process.env.PPLX_KEY
};

// Get appropriate research prompt
let researchConfig;
try {
  researchConfig = promptSelector.select('Research_Prompts', platform, researchType, {
    prompts,
    variables
  });
} catch (error) {
  // Fallback configuration
  researchConfig = {
    researchType: 'general',
    query: `trending ${variables.TOPIC} content`,
    endpoint: 'https://www.google.com/search',
    headers: {},
    updateFrequency: 'daily',
    priority: 'medium'
  };
}

// Check if we should fetch based on update frequency
const lastFetch = items[0].json.last_research_fetch || 0;
const now = Date.now();
const frequencyMap = {
  'hourly': 60 * 60 * 1000,
  '6_hours': 6 * 60 * 60 * 1000,
  '12_hours': 12 * 60 * 60 * 1000,
  'daily': 24 * 60 * 60 * 1000,
  'weekly': 7 * 24 * 60 * 60 * 1000
};
const updateInterval = frequencyMap[researchConfig.updateFrequency] || frequencyMap.daily;
const shouldFetch = (now - lastFetch) > updateInterval;

return [{
  json: {
    ...items[0].json,
    research_config: researchConfig,
    should_fetch: shouldFetch,
    last_fetch_age_hours: Math.round((now - lastFetch) / (60 * 60 * 1000)),
    variables
  }
}];

// Use cached data
const cacheKey = `research_${items[0].json.research_config.researchType}_${items[0].json.platform}`;
const cachedData = global[cacheKey] || null;

if (cachedData) {
  return [{
    json: {
      ...items[0].json,
      research_data: cachedData,
      data_source: 'cache',
      cache_age_hours: items[0].json.last_fetch_age_hours
    }
  }];
} else {
  // No cache available, return with flag
  return [{
    json: {
      ...items[0].json,
      research_data: null,
      data_source: 'none',
      error: 'No cached data available and fetch skipped due to rate limit'
    }
  }];
}

// Process and normalize research data
const researchConfig = items[0].json.research_config;
const rawData = $node['Fetch Research Data'].json;
const error = $node['Fetch Research Data'].error;

let processedData = {};
let trends = [];
let keywords = [];
let insights = [];

// Handle errors
if (error) {
  return [{
    json: {
      ...items[0].json,
      research_data: null,
      data_source: 'error',
      error: error.message || 'Failed to fetch research data',
      should_retry: true
    }
  }];
}

// Process based on research type
try {
  switch (researchConfig.researchType) {
    case 'Trending_Topics':
      // Macrocosmos format
      if (rawData.results) {
        trends = rawData.results.map(r => ({
          topic: r.title || r.topic,
          score: r.score || r.engagement_score || 0,
          source: r.source || 'macrocosmos',
          url: r.url
        }));
      }
      break;

    case 'Hashtags':
      // RiteTag format
      if (rawData.data) {
        keywords = rawData.data.map(tag => ({
          tag: tag.hashtag,
          tweets_per_hour: tag.tweets || 0,
          exposure: tag.exposure || 0,
          color: tag.color // hot, warm, cold
        }));
      }
      break;

    case 'Competitors':
      // BuzzSumo format
      if (rawData.articles) {
        insights = rawData.articles.map(a => ({
          title: a.title,
          shares: a.total_shares || 0,
          engagement: a.total_engagement || 0,
          url: a.url,
          published: a.published_date
        }));
      }
      break;

    case 'Keywords':
      // SerpAPI format
      if (rawData.related_searches) {
        keywords = rawData.related_searches.map(s => ({
          keyword: s.query,
          relevance: s.relevance_score || 0.5
        }));
      }
      break;

    case 'Industry_News':
      // Perplexity format
      if (rawData.answer) {
        insights = [{
          summary: rawData.answer,
          sources: rawData.sources || [],
          confidence: rawData.confidence || 0.8
        }];
      }
      break;
  }

  // Compile processed data
  processedData = {
    trends: trends.slice(0, 10), // Top 10
    keywords: keywords.slice(0, 20), // Top 20
    insights: insights.slice(0, 5), // Top 5
    raw_response: rawData,
    fetched_at: new Date().toISOString(),
    research_type: researchConfig.researchType
  };

  // Cache the data globally
  const cacheKey = `research_${researchConfig.researchType}_${items[0].json.platform}`;
  global[cacheKey] = processedData;

} catch (parseError) {
  console.error('Error processing research data:', parseError);
  processedData = {
    error: 'Failed to parse research data',
    raw_response: rawData
  };
}

return [{
  json: {
    ...items[0].json,
    research_data: processedData,
    data_source: 'fresh',
    last_research_fetch: Date.now()
  }
}];

// Merge research data from both paths
const allItems = [...$items('Process Research Data'), ...$items('Use Cached Data')];

// Find the item with actual data
const itemWithData = allItems.find(item => item.json.research_data && !item.json.error) || allItems[0];

// Enrich original idea with research
const enrichedIdea = {
  ...itemWithData.json,
  research_enriched: true,
  enrichment_summary: this.summarizeResearch(itemWithData.json.research_data)
};

function summarizeResearch(data) {
  if (!data) return 'No research data available';

  const summary = [];

  if (data.trends && data.trends.length > 0) {
    summary.push(`Top trends: ${data.trends.slice(0, 3).map(t => t.topic).join(', ')}`);
  }

  if (data.keywords && data.keywords.length > 0) {
    summary.push(`Key terms: ${data.keywords.slice(0, 5).map(k => k.tag || k.keyword).join(', ')}`);
  }

  if (data.insights && data.insights.length > 0) {
    summary.push(`${data.insights.length} insights discovered`);
  }

  return summary.join('. ') || 'Research completed';
}

return [enrichedIdea];
